import{_ as e,o,c as a,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Automation — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Automation — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/automation-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Automation — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/automation-production-readiness"}]]},"headers":[],"relativePath":"deployment/automation-production-readiness.md","filePath":"deployment/automation-production-readiness.md","lastUpdated":1788177880000}'),r={name:"deployment/automation-production-readiness.md"};function n(i,t,s,c,l,u){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="automation-—-production-readiness" tabindex="-1">Automation — Production Readiness <a class="header-anchor" href="#automation-—-production-readiness" aria-label="Permalink to &quot;Automation — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-13</td></tr><tr><td><strong>Status</strong></td><td>Ready for merge / staging go-live (billable Marketplace add-on)</td></tr><tr><td><strong>Scope</strong></td><td>Automation module <code>automation</code> v1.0.0</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/automation-module</code></td></tr><tr><td><strong>Companion</strong></td><td><a href="./automation">Automation production</a> · <a href="/developer-guide/automation">Developer guide</a> · <a href="/user-guide/automation">User guide</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Automation is a <strong>billable</strong> Marketplace SKU (<code>$29/mo</code>, <code>$290/yr</code>). It is <strong>not</strong> default-included. Workspaces install from Marketplace after migrate; existing tenants are unchanged until they subscribe.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong> for staging → production after CI on companion PRs and the ops follow-ups below.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Activation bypass closed (create inactive → <code>activate()</code>)</td><td>Pass</td></tr><tr><td>Outbound webhook SSRF + timeouts</td><td>Pass</td></tr><tr><td>Schedule 90s window + 2-minute dedup + cache lock</td><td>Pass</td></tr><tr><td>Run job <code>failed()</code> + per-run cache lock + <code>$timeout</code> 60s</td><td>Pass</td></tr><tr><td>Pest Automation suites</td><td>Pass (local) — confirm CI on Backend PR</td></tr><tr><td>Playwright <code>test:e2e:automation</code></td><td>Pass (local) — confirm on staging</td></tr><tr><td>Docs + marketing SKU</td><td>Pass</td></tr></tbody></table><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li><strong>Backend</strong> <code>php artisan migrate --force</code> (schema + catalog + permissions)</li><li>Update queue workers to include <strong><code>automations</code></strong> before <code>emails,default</code></li><li>Confirm scheduler: <code>automation:dispatch-schedules</code> every minute (<code>withoutOverlapping(5)</code>, <code>onOneServer</code>)</li><li>Deploy <strong>SPA</strong> (Automation nav + builder)</li><li>Deploy <strong>Docs</strong> + <strong>marketing site</strong></li><li>Staging smoke (below) before production traffic</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs → Website</strong>.</p><p>Optional env: <code>AUTOMATION_WEBHOOK_SECRET</code> (default HMAC when a webhook action omits its own secret).</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations applied on staging/prod (<code>automation_*</code> tables + catalog row + permission grants)</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Catalog shows <code>automation</code> published, billable, <strong>not</strong> default-included</td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Queue daemon: <code>--queue=automations,emails,default --timeout=90</code></td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Scheduler runs <code>automation:dispatch-schedules</code>; shared Redis/cache for <code>onOneServer</code></td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td><code>AUTOMATION_WEBHOOK_SECRET</code> set if default webhook HMAC is desired</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Frontend routes gated with <code>RequireAccess</code> (<code>module=automation</code>, <code>automation.view</code>)</td><td>QA</td><td>☐</td></tr><tr><td>7</td><td>Pest Automation suites green in CI</td><td>Eng</td><td>☐</td></tr><tr><td>8</td><td>Playwright <code>npm run test:e2e:automation</code> green on staging</td><td>QA</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → install <strong>Automation</strong> (paid add-on; test gateway / entitled workspace)</li><li>Sidebar shows <strong>Automation</strong> for a role with <code>automation.view</code></li><li>Templates → Use template → workflow opens <strong>inactive</strong></li><li>Save &amp; activate a <strong>Manual</strong> + Create task (or notification) workflow</li><li><strong>Run</strong> → Runs page shows pending/running then completed or failed with logs</li><li>Pick an unwired trigger (Contact created) → <strong>Save &amp; activate</strong> stays disabled / API 422; workflow remains inactive</li><li>Optional: schedule daily <code>H:i</code> in workspace timezone; wait for dispatcher; confirm a single run (no duplicates)</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA; Automation nav disappears until re-deploy</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep migrations (catalog insert is additive)</td></tr><tr><td>Module disable</td><td>Marketplace uninstall / cancel subscription (workflow rows retained)</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> roll back Automation migrations in production without a data plan</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Run statuses: <code>pending</code> / <code>running</code> / <code>completed</code> / <code>failed</code> / <code>skipped</code> / <code>cancelled</code></li><li><code>automation_logs</code> step detail; Nightwatch on <code>ExecuteAutomationRunJob</code> and <code>automation:dispatch-schedules</code></li><li>Failed jobs: <code>php artisan queue:failed</code> on the <code>automations</code> queue</li><li>Platform audit + Spatie activity on workflow CRUD</li></ul><hr><h2 id="accepted-residual-risk" tabindex="-1">Accepted residual risk <a class="header-anchor" href="#accepted-residual-risk" aria-label="Permalink to &quot;Accepted residual risk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Severity</th><th>Notes</th></tr></thead><tbody><tr><td>DNS-rebinding to private IPs after hostname allow</td><td>Low</td><td>Literal private IPs and localhost are blocked; hostname resolve is best-effort</td></tr><tr><td>Unwired catalog triggers visible in builder</td><td>Info</td><td>Cannot activate; intentional stubs</td></tr><tr><td>Delay continuation uses the same run id</td><td>Info</td><td>Per-run cache lock waits then continues; do not use <code>ShouldBeUnique</code> on run id</td></tr><tr><td>Staff default role includes <code>automation.run</code></td><td>Info</td><td>Same pattern as other module defaults; customize per workspace</td></tr></tbody></table><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Eng</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>QA</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>Ops</td><td></td><td></td><td>☐ Ready</td></tr></tbody></table><p><strong>Release decision:</strong> Ready for production opt-in after CI green and staging smoke.</p>',31)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
